<script lang="ts">
	import { getContext, createEventDispatcher, onMount, onDestroy } from 'svelte';

	const i18n = getContext('i18n');
	const dispatch = createEventDispatcher();

	import ChevronDown from '../icons/ChevronDown.svelte';
	import ChevronRight from '../icons/ChevronRight.svelte';
	import Collapsible from './Collapsible.svelte';
	import Tooltip from './Tooltip.svelte';
	import Plus from '../icons/Plus.svelte';

	export let open = true;

	export let id = '';
	export let name = '';
	export let collapsible = true;

	export let className = '';
	export let buttonClassName = 'text-gray-600 dark:text-gray-400';

	export let chevron = true;
	export let onAddLabel: string = '';
	export let onAdd: null | Function = null;

	export let dragAndDrop = true;

	let folderElement;
	let loaded = false;

	let draggedOver = false;

	const onDragOver = (e) => {
		e.preventDefault();
		e.stopPropagation();
		draggedOver = true;
	};

	const onDrop = (e) => {
		e.preventDefault();
		e.stopPropagation();

		if (folderElement.contains(e.target)) {
			console.log('Dropped on the Button');

			if (e.dataTransfer.items && e.dataTransfer.items.length > 0) {
				// Iterate over all items in the DataTransferItemList use functional programming
				for (const item of Array.from(e.dataTransfer.items)) {
					// If dropped items aren't files, reject them
					if (item.kind === 'file') {
						const file = item.getAsFile();
						if (file && file.type === 'application/json') {
							console.log('Dropped file is a JSON file!');

							// Read the JSON file with FileReader
							const reader = new FileReader();
							reader.onload = async function (event) {
								try {
									const fileContent = JSON.parse(event.target.result);
									console.log('Parsed JSON Content: ', fileContent);
									open = true;
									dispatch('import', fileContent);
								} catch (error) {
									console.error('Error parsing JSON file:', error);
								}
							};

							// Start reading the file
							reader.readAsText(file);
						} else {
							console.error('Only JSON file types are supported.');
						}
					} else {
						open = true;
						try {
							const dataTransfer = e.dataTransfer.getData('text/plain');
							if (dataTransfer) {
								const data = JSON.parse(dataTransfer);
								console.log(data);
								dispatch('drop', data);
							} else {
								console.log('Dropped text data is empty or not text/plain.');
							}
						} catch (error) {
							console.log(
								'Dropped data is not valid JSON text or is empty. Ignoring drop event for this type of data.'
							);
						} finally {
							draggedOver = false;
						}

						// Only process the first non-file item; all share the same
						// text/plain payload, so continuing would duplicate the drop.
						break;
					}
				}
			}

			draggedOver = false;
		}
	};

	const onDragLeave = (e) => {
		e.preventDefault();
		e.stopPropagation();

		draggedOver = false;
	};

	onMount(() => {
		const state = localStorage.getItem(`${id}-folder-state`);
		if (state !== null) {
			open = state === 'true';
		}

		loaded = true;

		if (!dragAndDrop) {
			return;
		}
		folderElement.addEventListener('dragover', onDragOver);
		folderElement.addEventListener('drop', onDrop);
		folderElement.addEventListener('dragleave', onDragLeave);
	});

	onDestroy(() => {
		if (!dragAndDrop) {
			return;
		}
		folderElement.removeEventListener('dragover', onDragOver);
		folderElement.removeEventListener('drop', onDrop);
		folderElement.removeEventListener('dragleave', onDragLeave);
	});
</script>

<div bind:this={folderElement} class="relative {className}">
	{#if loaded}
		{#if draggedOver}
			<div
				class="pointer-events-none absolute inset-0 z-50 touch-none bg-black/[0.02] ring-1 ring-inset ring-black/10 dark:bg-white/[0.02] dark:ring-white/10"
			></div>
		{/if}

		{#if collapsible}
			<Collapsible
				bind:open
				className="w-full "
				buttonClassName="w-full"
				onChange={(state) => {
					dispatch('change', state);
					localStorage.setItem(`${id}-folder-state`, `${state}`);
				}}
			>
				<!-- svelte-ignore a11y-no-static-element-interactions -->
				<div
					id="sidebar-folder-button"
					class=" w-full group rounded-xl relative flex items-center justify-between hover:bg-gray-100 dark:hover:bg-gray-900 transition {buttonClassName}"
				>
					<h3 class="w-full">
						<button
							id={id ? `${id}-button` : undefined}
							class="w-full py-1.5 pl-2 flex items-center gap-1.5 text-xs font-normal"
						>
							{#if chevron}
								<div class=" p-[0.0625rem]">
									{#if open}
										<ChevronDown className=" size-3" strokeWidth="2" />
									{:else}
										<ChevronRight className=" size-3" strokeWidth="2" />
									{/if}
								</div>
							{/if}

							<div class="translate-y-[0.5px] {chevron ? '' : 'pl-0.5'}">
								{name}
							</div>
						</button>
					</h3>

					{#if onAdd}
						<button
							class="absolute z-10 right-2 hover-reveal self-center flex items-center dark:text-gray-300"
							on:pointerup={(e) => {
								e.stopPropagation();
							}}
							on:click={(e) => {
								e.stopPropagation();
								onAdd();
							}}
						>
							<Tooltip content={onAddLabel}>
								<button
									class="p-0.5 dark:hover:bg-gray-850 rounded-lg touch-auto"
									on:click={(e) => {}}
								>
									<Plus className=" size-3" strokeWidth="2.5" />
								</button>
							</Tooltip>
						</button>
					{/if}
				</div>

				<div slot="content" class="w-full">
					<slot></slot>
				</div>
			</Collapsible>
		{:else}
			<slot></slot>
		{/if}
	{/if}
</div>
